import json, re, sys, os
run = sys.argv[1]
raw = json.load(open(os.path.join(run, "raw-returns.json")))
def key(rv, f):
    return (rv, os.path.normpath(f["file"]), str(f["line"]), re.sub(r"\s+", " ", f["title"]).strip().lower())
detail = {}
for rv in ["correctness","security","adversarial","testing","reliability","api-contract"]:
    art = json.load(open(os.path.join(run, rv + ".json")))
    for f in art["findings"]:
        detail[key(rv, f)] = {"why_it_matters": f.get("why_it_matters"), "evidence": f.get("evidence", [])}
missing = []
for ret in raw:
    for f in ret["findings"]:
        k = key(ret["reviewer"], f)
        if k in detail:
            f["evidence"] = list(detail[k]["evidence"])
        elif ret["reviewer"] != "fast-pass":
            missing.append(k)
json.dump(raw, open(os.path.join(run, "helper-input-1.json"), "w"), indent=2)
json.dump({"__".join(k): v for k, v in detail.items()}, open(os.path.join(run, "source-detail-map.json"), "w"), indent=2)
print("detail entries:", len(detail), "unmatched:", missing)
EOF
